window.POSTER_FONT_CSS = "@font-face{font-family:'Bricolage Grotesque';font-style:normal;font-weight:500 800;font-display:block;src:url(data:font/woff2;base64,) format('woff2');}@font-face{font-family:'Orbitron';font-style:normal;font-weight:700 900;font-display:block;src:url(data:font/woff2;base64,) format('woff2');}@font-face{font-family:'Space Mono';font-style:normal;font-weight:400;font-display:block;src:url(data:font/woff2;base64,) format('woff2');}@font-face{font-family:'Space Mono';font-style:normal;font-weight:700;font-display:block;src:url(data:font/woff2;base64,) format('woff2');}@font-face{font-family:'Unbounded';font-style:normal;font-weight:500 900;font-display:block;src:url(data:font/woff2;base64,) format('woff2');}";
(function () { const s = document.createElement('style'); s.textContent = window.POSTER_FONT_CSS; document.head.appendChild(s); })();
